IF COL_LENGTH(N'OPS.ProducerRenewalCall', N'StatusCode') IS NULL ALTER TABLE OPS.ProducerRenewalCall ADD StatusCode NVARCHAR(50) NOT NULL CONSTRAINT DF_ProducerRenewalCall_Status_0165 DEFAULT N'Open';
