    INSERT INTO Client.ContactWorkflowEvent (WorkflowEventId,TenantId,ContactId,EventType,EventTitle,EventDetail,RelatedEntityName,RelatedEntityId,EventDateUtc,CreatedDateUtc,CreatedByUserId,IsDeleted)
