EXEC(N'
DECLARE @TenantId UNIQUEIDENTIFIER = ''00000000-0000-0000-0000-000000000001'';
DECLARE @AccountId UNIQUEIDENTIFIER = NULL;
DECLARE @AgreementId UNIQUEIDENTIFIER = ''b1000000-0000-0000-0000-000000000001'';
