    SELECT TOP 1 @Account4 = AccountId FROM Client.Account WHERE TenantId = @TenantId AND IsDeleted = 0 AND AccountId NOT IN (@Account1, COALESCE(@Account2, @Account1), COALESCE(@Account3, @Account1)) ORDER BY CreatedDateUtc;
