        ActionCode NVARCHAR(100) NOT NULL,
        ActionDescription NVARCHAR(500) NULL,
        OldValue NVARCHAR(MAX) NULL,
        NewValue NVARCHAR(MAX) NULL,
        ChangedByUserId UNIQUEIDENTIFIER NULL,
        IpAddress NVARCHAR(50) NULL,
        UserAgent NVARCHAR(500) NULL,
        SessionId NVARCHAR(200) NULL,
        StatusCode NVARCHAR(50) NOT NULL CONSTRAINT DF_UserAuditTrail_Status_0177 DEFAULT N'Success',
        ErrorDetails NVARCHAR(MAX) NULL,
        CreatedDateUtc DATETIME2 NOT NULL CONSTRAINT DF_UserAuditTrail_Created_0177 DEFAULT SYSUTCDATETIME(),
        ModifiedDateUtc DATETIME2 NULL,
        ModifiedByUserId UNIQUEIDENTIFIER NULL,
        IsDeleted BIT NOT NULL CONSTRAINT DF_UserAuditTrail_IsDeleted_0177 DEFAULT 0
    );
END;

IF COL_LENGTH(N'IAM.UserAuditTrail', N'ModifiedDateUtc') IS NULL ALTER TABLE IAM.UserAuditTrail ADD ModifiedDateUtc DATETIME2 NULL;
IF COL_LENGTH(N'IAM.UserAuditTrail', N'ModifiedByUserId') IS NULL ALTER TABLE IAM.UserAuditTrail ADD ModifiedByUserId UNIQUEIDENTIFIER NULL;
IF COL_LENGTH(N'IAM.UserAuditTrail', N'IsDeleted') IS NULL ALTER TABLE IAM.UserAuditTrail ADD IsDeleted BIT NOT NULL CONSTRAINT DF_UserAuditTrail_IsDeleted_0177B DEFAULT 0;

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'IAM.UserAuditTrail') AND name = N'IX_UserAuditTrail_UserId')
    CREATE INDEX IX_UserAuditTrail_UserId ON IAM.UserAuditTrail(UserId, CreatedDateUtc DESC);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'IAM.UserAuditTrail') AND name = N'IX_UserAuditTrail_TenantId')
    CREATE INDEX IX_UserAuditTrail_TenantId ON IAM.UserAuditTrail(TenantId, CreatedDateUtc DESC);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'IAM.UserAuditTrail') AND name = N'IX_UserAuditTrail_ActionCode')
    CREATE INDEX IX_UserAuditTrail_ActionCode ON IAM.UserAuditTrail(ActionCode, CreatedDateUtc DESC);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'IAM.UserAuditTrail') AND name = N'IX_UserAuditTrail_StatusCode')
    CREATE INDEX IX_UserAuditTrail_StatusCode ON IAM.UserAuditTrail(StatusCode, CreatedDateUtc DESC);

IF OBJECT_ID(N'IAM.UserAuditActionType', N'U') IS NULL
BEGIN
    CREATE TABLE IAM.UserAuditActionType
    (
        UserAuditActionTypeId UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_UserAuditActionType PRIMARY KEY DEFAULT NEWID(),
        TenantId UNIQUEIDENTIFIER NOT NULL,
        ActionCode NVARCHAR(100) NOT NULL,
        ActionName NVARCHAR(200) NOT NULL,
        CategoryCode NVARCHAR(50) NOT NULL CONSTRAINT DF_UserAuditActionType_Category_0177 DEFAULT N'User',
        SeverityCode NVARCHAR(50) NOT NULL CONSTRAINT DF_UserAuditActionType_Severity_0177 DEFAULT N'Info',
        Description NVARCHAR(500) NULL,
        SortOrder INT NOT NULL CONSTRAINT DF_UserAuditActionType_Sort_0177 DEFAULT 0,
        IsActive BIT NOT NULL CONSTRAINT DF_UserAuditActionType_Active_0177 DEFAULT 1,
        CreatedDateUtc DATETIME2 NOT NULL CONSTRAINT DF_UserAuditActionType_Created_0177 DEFAULT SYSUTCDATETIME(),
        CreatedByUserId UNIQUEIDENTIFIER NULL,
        ModifiedDateUtc DATETIME2 NULL,
        ModifiedByUserId UNIQUEIDENTIFIER NULL,
        IsDeleted BIT NOT NULL CONSTRAINT DF_UserAuditActionType_IsDeleted_0177 DEFAULT 0,
        CONSTRAINT UQ_UserAuditActionType_Tenant_Action UNIQUE (TenantId, ActionCode)
    );
END;

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'IAM.UserAuditActionType') AND name = N'IX_UserAuditActionType_Tenant_Category')
    CREATE INDEX IX_UserAuditActionType_Tenant_Category ON IAM.UserAuditActionType(TenantId, CategoryCode, SortOrder);

DECLARE @TenantId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 TenantId FROM Core.Tenant ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000001');
DECLARE @AdminUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] WHERE TenantId = @TenantId ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000002');
DECLARE @ManagerUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] WHERE TenantId = @TenantId AND UserId <> @AdminUserId ORDER BY CreatedDateUtc), @AdminUserId);
DECLARE @StandardUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] WHERE TenantId = @TenantId AND UserId NOT IN (@AdminUserId, @ManagerUserId) ORDER BY CreatedDateUtc), @ManagerUserId);

