    (NEWID(), @TenantId, @StandardUserId, N'ACCOUNT_UNLOCKED', N'Account unlocked by administrator.', N'Locked', N'Active', @AdminUserId, N'192.168.1.100', N'Mozilla/5.0 Chrome', NULL, N'Success', NULL, DATEADD(hour, -12, SYSUTCDATETIME())),
