        TenantId UNIQUEIDENTIFIER NOT NULL,
        ActorUserId UNIQUEIDENTIFIER NULL,
        ActorUserName NVARCHAR(300) NULL,
        ActorRole NVARCHAR(200) NULL,
        ActorType NVARCHAR(100) NOT NULL CONSTRAINT DF_AuditEvent_ActorType DEFAULT N'User',
        ActionType NVARCHAR(100) NOT NULL,
        ActionCategory NVARCHAR(100) NOT NULL,
        ModuleName NVARCHAR(100) NOT NULL,
        EntityName NVARCHAR(256) NULL,
        EntityId UNIQUEIDENTIFIER NULL,
        EntityDisplayName NVARCHAR(300) NULL,
        ParentEntityName NVARCHAR(256) NULL,
        ParentEntityId UNIQUEIDENTIFIER NULL,
        OldValue NVARCHAR(MAX) NULL,
        NewValue NVARCHAR(MAX) NULL,
        IpAddress NVARCHAR(64) NULL,
        UserAgent NVARCHAR(500) NULL,
        CorrelationId NVARCHAR(120) NULL,
        RequestId NVARCHAR(120) NULL,
        SourceSystem NVARCHAR(100) NOT NULL CONSTRAINT DF_AuditEvent_Source DEFAULT N'Web',
        Severity NVARCHAR(50) NOT NULL CONSTRAINT DF_AuditEvent_Severity DEFAULT N'Info',
        StatusCode NVARCHAR(50) NOT NULL CONSTRAINT DF_AuditEvent_Status DEFAULT N'Success',
        IsSensitiveData BIT NOT NULL CONSTRAINT DF_AuditEvent_IsSensitive DEFAULT 0,
        IsPiiMasked BIT NOT NULL CONSTRAINT DF_AuditEvent_IsPiiMasked DEFAULT 0,
        IsLegalHold BIT NOT NULL CONSTRAINT DF_AuditEvent_IsLegalHold DEFAULT 0,
        ChangeReason NVARCHAR(500) NULL,
        VersionNumber INT NULL,
        MetadataJson NVARCHAR(MAX) NULL,
        CreatedUtc DATETIME2 NOT NULL CONSTRAINT DF_AuditEvent_Created DEFAULT SYSUTCDATETIME()
    );
END;

IF OBJECT_ID(N'Audit.AuditEventDetail', N'U') IS NULL
BEGIN
    CREATE TABLE Audit.AuditEventDetail
