        AuditEventDetailId UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_AuditEventDetail PRIMARY KEY DEFAULT NEWID(),
        TenantId UNIQUEIDENTIFIER NOT NULL,
        AuditEventId UNIQUEIDENTIFIER NOT NULL,
        DetailName NVARCHAR(200) NOT NULL,
        OldValue NVARCHAR(MAX) NULL,
        NewValue NVARCHAR(MAX) NULL,
        DataTypeCode NVARCHAR(50) NULL,
        IsSensitive BIT NOT NULL CONSTRAINT DF_AuditEventDetail_IsSensitive DEFAULT 0,
        IsMasked BIT NOT NULL CONSTRAINT DF_AuditEventDetail_IsMasked DEFAULT 0,
        CreatedUtc DATETIME2 NOT NULL CONSTRAINT DF_AuditEventDetail_Created DEFAULT SYSUTCDATETIME()
    );
END;

