IF OBJECT_ID(N'Audit.AuditAlertEvent', N'U') IS NULL
    CREATE TABLE Audit.AuditAlertEvent (AuditAlertEventId UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_AuditAlertEvent PRIMARY KEY DEFAULT NEWID(), TenantId UNIQUEIDENTIFIER NOT NULL, AuditEventId UNIQUEIDENTIFIER NULL, AlertCode NVARCHAR(100) NOT NULL, AlertName NVARCHAR(200) NOT NULL, Severity NVARCHAR(50) NOT NULL, StatusCode NVARCHAR(50) NOT NULL CONSTRAINT DF_AuditAlertEvent_Status DEFAULT N'Open', Description NVARCHAR(1000) NULL, AssignedToUserId UNIQUEIDENTIFIER NULL, CreatedUtc DATETIME2 NOT NULL CONSTRAINT DF_AuditAlertEvent_Created DEFAULT SYSUTCDATETIME());

IF OBJECT_ID(N'Audit.AuditCapability', N'U') IS NULL
    CREATE TABLE Audit.AuditCapability (AuditCapabilityId UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_AuditCapability PRIMARY KEY DEFAULT NEWID(), TenantId UNIQUEIDENTIFIER NULL, CapabilityArea NVARCHAR(100) NOT NULL, FeatureName NVARCHAR(200) NOT NULL, Purpose NVARCHAR(500) NOT NULL, ModuleName NVARCHAR(100) NOT NULL, ActionType NVARCHAR(100) NOT NULL, IsImplemented BIT NOT NULL CONSTRAINT DF_AuditCapability_Implemented DEFAULT 1, IsSeeded BIT NOT NULL CONSTRAINT DF_AuditCapability_Seeded DEFAULT 1, RequiresInstrumentation BIT NOT NULL CONSTRAINT DF_AuditCapability_RequiresInstrumentation DEFAULT 1, DisplayOrder INT NOT NULL CONSTRAINT DF_AuditCapability_DisplayOrder DEFAULT 0, CreatedUtc DATETIME2 NOT NULL CONSTRAINT DF_AuditCapability_Created DEFAULT SYSUTCDATETIME());

