    private const string Migration0181_CarrierUserAuditActionTypesSync = @"
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N'IAM') EXEC(N'CREATE SCHEMA IAM');

DECLARE @TenantId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 TenantId FROM Core.Tenant ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000001');
DECLARE @AdminUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] WHERE TenantId = @TenantId ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000002');

DECLARE @CarrierActionTypes TABLE (ActionCode NVARCHAR(100), ActionName NVARCHAR(200), CategoryCode NVARCHAR(50), SeverityCode NVARCHAR(50), Description NVARCHAR(500), SortOrder INT);
INSERT INTO @CarrierActionTypes VALUES
(N'CARRIER_CREATED', N'Carrier Created', N'Configuration', N'Info', N'A carrier configuration record was created.', 1810),
(N'CARRIER_UPDATED', N'Carrier Updated', N'Configuration', N'Medium', N'A carrier configuration record was updated.', 1820),
(N'CARRIER_NAME_CHANGED', N'Carrier Name Changed', N'Configuration', N'Medium', N'A carrier name was changed.', 1830),
(N'CARRIER_NAIC_CHANGED', N'Carrier NAIC Changed', N'Configuration', N'Medium', N'A carrier NAIC code was changed.', 1840),
(N'CARRIER_RATING_CHANGED', N'Carrier Rating Changed', N'Configuration', N'Medium', N'A carrier AM Best rating was changed.', 1850),
(N'CARRIER_MARKET_TYPE_CHANGED', N'Carrier Market Type Changed', N'Configuration', N'Medium', N'A carrier admitted/non-admitted market setting was changed.', 1860),
(N'CARRIER_APPOINTMENT_CHANGED', N'Carrier Appointment Changed', N'Configuration', N'Medium', N'A carrier appointment date was changed.', 1870),
(N'CARRIER_ACTIVATED', N'Carrier Activated', N'Configuration', N'Medium', N'A carrier was activated.', 1880),
(N'CARRIER_DEACTIVATED', N'Carrier Deactivated', N'Configuration', N'Medium', N'A carrier was deactivated.', 1890);

INSERT INTO IAM.UserAuditActionType
(UserAuditActionTypeId, TenantId, ActionCode, ActionName, CategoryCode, SeverityCode, Description, SortOrder, IsActive, CreatedDateUtc, CreatedByUserId, IsDeleted)
SELECT NEWID(), @TenantId, a.ActionCode, a.ActionName, a.CategoryCode, a.SeverityCode, a.Description, a.SortOrder, 1, SYSUTCDATETIME(), @AdminUserId, 0
FROM @CarrierActionTypes a
WHERE NOT EXISTS (SELECT 1 FROM IAM.UserAuditActionType existing WHERE existing.TenantId = @TenantId AND existing.ActionCode = a.ActionCode);
";

