    private const string Migration0183_CommonEntityUserAuditActionTypesSync = @"
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N'IAM') EXEC(N'CREATE SCHEMA IAM');

DECLARE @TenantId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 TenantId FROM Core.Tenant ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000001');
DECLARE @AdminUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] WHERE TenantId = @TenantId ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000002');

DECLARE @EntityActions TABLE (EntityCode NVARCHAR(100), EntityName NVARCHAR(200), SortOrder INT);
INSERT INTO @EntityActions VALUES
(N'ACCOUNT', N'Account', 2010),
(N'CONTACT', N'Contact', 2020),
(N'LEAD', N'Lead', 2030),
(N'OPPORTUNITY', N'Opportunity', 2040),
(N'SUBMISSION', N'Submission', 2050),
(N'QUOTE', N'Quote', 2060),
(N'POLICY', N'Policy', 2070),
(N'CLAIM', N'Claim', 2080),
(N'DOCUMENT', N'Document', 2090),
(N'INVOICE', N'Invoice', 2100),
(N'PAYMENT', N'Payment', 2110),
(N'BRANCH', N'Branch', 2120),
(N'USER', N'User', 2130),
(N'ROLE', N'Role', 2140),
(N'AGREEMENT', N'Agreement', 2150),
(N'AUTOMATION_FLOW', N'Automation Flow', 2160),
(N'ACCOUNT_SEGMENT', N'Account Segment', 2170),
(N'ACCOUNT_SEGMENT_RULE', N'Account Segment Rule', 2180),
(N'AR_AGING', N'AR Aging', 2190),
(N'AI_CONFIG', N'AI Configuration', 2200),
(N'CARRIER', N'Carrier', 2210);

DECLARE @SpecificActions TABLE (ActionCode NVARCHAR(100), ActionName NVARCHAR(200), CategoryCode NVARCHAR(50), SeverityCode NVARCHAR(50), Description NVARCHAR(500), SortOrder INT);

INSERT INTO @SpecificActions
SELECT EntityCode + N'_CREATED', EntityName + N' Created', N'Configuration', N'Info', EntityName + N' record was created.', SortOrder
FROM @EntityActions;

INSERT INTO @SpecificActions
SELECT EntityCode + N'_UPDATED', EntityName + N' Updated', N'Data Change', N'Medium', EntityName + N' record was updated.', SortOrder + 1
FROM @EntityActions;

INSERT INTO @SpecificActions
SELECT EntityCode + N'_DELETED', EntityName + N' Deleted', N'Data Change', N'High', EntityName + N' record was deleted or soft-deleted.', SortOrder + 2
FROM @EntityActions;

MERGE IAM.UserAuditActionType AS target
USING @SpecificActions AS source
ON target.TenantId = @TenantId AND target.ActionCode = source.ActionCode
WHEN MATCHED THEN
    UPDATE SET ActionName = source.ActionName,
               CategoryCode = source.CategoryCode,
               SeverityCode = source.SeverityCode,
               Description = source.Description,
               SortOrder = source.SortOrder,
               IsActive = 1,
               IsDeleted = 0,
               ModifiedDateUtc = SYSUTCDATETIME(),
               ModifiedByUserId = @AdminUserId
WHEN NOT MATCHED THEN
    INSERT (UserAuditActionTypeId, TenantId, ActionCode, ActionName, CategoryCode, SeverityCode, Description, SortOrder, IsActive, CreatedDateUtc, CreatedByUserId, IsDeleted)
    VALUES (NEWID(), @TenantId, source.ActionCode, source.ActionName, source.CategoryCode, source.SeverityCode, source.Description, source.SortOrder, 1, SYSUTCDATETIME(), @AdminUserId, 0);
";

    private const string Migration0184_AuditSensitiveFieldCatalogCreateSeed = @"
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N'Audit') EXEC(N'CREATE SCHEMA Audit');

IF OBJECT_ID(N'Audit.AuditSensitiveField', N'U') IS NULL
BEGIN
    CREATE TABLE Audit.AuditSensitiveField
    (
        AuditSensitiveFieldId UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_AuditSensitiveField PRIMARY KEY DEFAULT NEWID(),
        TenantId UNIQUEIDENTIFIER NULL,
        EntityName NVARCHAR(256) NULL,
        FieldNamePattern NVARCHAR(256) NOT NULL,
        Description NVARCHAR(500) NULL,
        IsActive BIT NOT NULL CONSTRAINT DF_AuditSensitiveField_Active DEFAULT 1,
        CreatedDateUtc DATETIME2 NOT NULL CONSTRAINT DF_AuditSensitiveField_Created DEFAULT SYSUTCDATETIME(),
        CreatedByUserId UNIQUEIDENTIFIER NULL,
        ModifiedDateUtc DATETIME2 NULL,
        ModifiedByUserId UNIQUEIDENTIFIER NULL,
        IsDeleted BIT NOT NULL CONSTRAINT DF_AuditSensitiveField_IsDeleted DEFAULT 0
    );
END;

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'Audit.AuditSensitiveField') AND name = N'IX_AuditSensitiveField_Tenant_Entity')
    CREATE INDEX IX_AuditSensitiveField_Tenant_Entity ON Audit.AuditSensitiveField(TenantId, EntityName, IsActive) INCLUDE (FieldNamePattern);

DECLARE @AdminUserId UNIQUEIDENTIFIER = COALESCE((SELECT TOP 1 UserId FROM IAM.[User] ORDER BY CreatedDateUtc), '00000000-0000-0000-0000-000000000002');

DECLARE @Patterns TABLE (FieldNamePattern NVARCHAR(256), Description NVARCHAR(500));
INSERT INTO @Patterns VALUES
(N'%Password%', N'Password and password-hash fields.'),
(N'%Secret%', N'Client secrets and shared secrets.'),
(N'%ApiKey%', N'API key credentials.'),
(N'%AccessToken%', N'OAuth or bearer access tokens.'),
(N'%RefreshToken%', N'OAuth refresh tokens.'),
(N'%PrivateKey%', N'Private key material.'),
(N'Ssn', N'Social Security Number.'),
(N'%SocialSecurity%', N'Social Security Number variants.'),
(N'%TaxId%', N'Tax identification numbers.'),
(N'%Ein%', N'Employer identification numbers.'),
(N'%CreditCard%', N'Credit card numbers.'),
(N'%CardNumber%', N'Payment card numbers.'),
(N'%SecurityCode%', N'Card security codes (CVV).'),
(N'%BankAccount%', N'Bank account numbers.'),
(N'%RoutingNumber%', N'Bank routing numbers.'),
(N'%AccountNumber%', N'Financial account numbers.'),
(N'DateOfBirth', N'Date of birth.'),
(N'%DriversLicense%', N'Driver license numbers.'),
(N'%PassportNumber%', N'Passport numbers.'),
(N'%MedicalRecord%', N'Medical record identifiers.');

MERGE Audit.AuditSensitiveField AS target
USING @Patterns AS source
ON target.TenantId IS NULL AND target.EntityName IS NULL AND target.FieldNamePattern = source.FieldNamePattern
WHEN MATCHED THEN
    UPDATE SET Description = source.Description,
               IsActive = 1,
               IsDeleted = 0,
               ModifiedDateUtc = SYSUTCDATETIME(),
               ModifiedByUserId = @AdminUserId
WHEN NOT MATCHED THEN
    INSERT (AuditSensitiveFieldId, TenantId, EntityName, FieldNamePattern, Description, IsActive, CreatedDateUtc, CreatedByUserId, IsDeleted)
    VALUES (NEWID(), NULL, NULL, source.FieldNamePattern, source.Description, 1, SYSUTCDATETIME(), @AdminUserId, 0);
";

    private const string Migration0185_AuditActorAttributionDataSync = @"
-- Remap IAM.UserAuditTrail rows whose UserId/ChangedByUserId have no IAM.[User] row
-- (e.g. legacy dev-auth placeholder ids) to the tenant's first active user so
-- user name and email always resolve from the database.
UPDATE a SET a.UserId = fallback.UserId
FROM IAM.UserAuditTrail a
CROSS APPLY (SELECT TOP 1 u.UserId FROM IAM.[User] u
             WHERE u.TenantId = a.TenantId AND u.IsDeleted = 0 AND u.IsActive = 1
             ORDER BY u.CreatedDateUtc) fallback
WHERE NOT EXISTS (SELECT 1 FROM IAM.[User] u WHERE u.UserId = a.UserId AND u.IsDeleted = 0);

UPDATE a SET a.ChangedByUserId = a.UserId
FROM IAM.UserAuditTrail a
WHERE a.ChangedByUserId IS NULL
   OR NOT EXISTS (SELECT 1 FROM IAM.[User] u WHERE u.UserId = a.ChangedByUserId AND u.IsDeleted = 0);

-- Remap Audit.AuditEvent actor ids the same way, then backfill name/role from IAM.
UPDATE e SET e.ActorUserId = fallback.UserId
FROM Audit.AuditEvent e
CROSS APPLY (SELECT TOP 1 u.UserId FROM IAM.[User] u
             WHERE u.TenantId = e.TenantId AND u.IsDeleted = 0 AND u.IsActive = 1
             ORDER BY u.CreatedDateUtc) fallback
WHERE e.ActorType = N'User'
  AND (e.ActorUserId IS NULL
       OR NOT EXISTS (SELECT 1 FROM IAM.[User] u WHERE u.UserId = e.ActorUserId AND u.IsDeleted = 0));

UPDATE e SET
    e.ActorUserName = COALESCE(NULLIF(u.FullName, N''), NULLIF(u.UserName, N''), u.Email),
    e.ActorRole = COALESCE(
        LEFT((SELECT STRING_AGG(r.RoleName, N', ') WITHIN GROUP (ORDER BY r.RoleName)
              FROM IAM.UserRole ur
              JOIN IAM.Role r ON r.RoleId = ur.RoleId AND r.IsDeleted = 0 AND r.IsActive = 1
              WHERE ur.UserId = u.UserId AND ur.IsDeleted = 0 AND ur.IsActive = 1), 200),
        e.ActorRole)
FROM Audit.AuditEvent e
JOIN IAM.[User] u ON u.UserId = e.ActorUserId AND u.IsDeleted = 0
WHERE e.ActorUserName IS NULL OR e.ActorUserName IN (N'', N'Unknown User', N'Development User');

-- Backfill AuditEntityChange.ChangedByUserId from the parent event when missing or orphaned.
UPDATE c SET c.ChangedByUserId = e.ActorUserId
FROM Audit.AuditEntityChange c
JOIN Audit.AuditEvent e ON e.AuditEventId = c.AuditEventId
WHERE c.ChangedByUserId IS NULL
   OR NOT EXISTS (SELECT 1 FROM IAM.[User] u WHERE u.UserId = c.ChangedByUserId AND u.IsDeleted = 0);
";

