    IF COL_LENGTH(N'Submissions.PolicyCreationSource', N'RecommendedDocumentTypeCode') IS NULL ALTER TABLE Submissions.PolicyCreationSource ADD RecommendedDocumentTypeCode NVARCHAR(80) NULL;
